        vm.assume(amount > 0);
        c.AdjustBetAmounts(amount);
        vm.recordLogs();
        c.AdjustBetAmounts(amount);
        bool ok = false;
        Vm.Log[] memory entries = vm.getRecordedLogs();
        for (uint i = 0; i < entries.length; i++) {
            if (entries[i].topics[0] == keccak256("BetLimitChanged(uint256)")) {
                uint256 val = abi.decode(entries[i].data, (uint256));
                if (val == amount) {
                    ok = true;
                }
            }
        }
        assertTrue(ok);
    }
}

