pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 initialDiff, uint256 betAmount, uint256 nextBetAmount) public {
        vm.assume(initialDiff > 0);
        vm.assume(betAmount > 0);
        vm.assume(nextBetAmount > 0);
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustDifficulty(initialDiff);
        vm.prank(address(this));
        c.AdjustBetAmounts(betAmount);
        uint256 diffBefore = c.currentDifficulty();
        vm.prank(address(this));
        c.AdjustBetAmounts(nextBetAmount);
        uint256 diffAfter = c.currentDifficulty();
        assertEq(diffAfter, diffBefore, "difficulty changed after AdjustBetAmounts");
    }
}

