pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount, uint256 diffAmount) public {
        vm.assume(amount > 0 && diffAmount > 0);
        // Call AdjustDifficulty to set difficulty to a non-zero value
        vm.prank(address(this));
        c.AdjustDifficulty(diffAmount);
        uint256 diffBefore = c.currentDifficulty();
        // Call AdjustBetAmounts and then check that difficulty remains unchanged
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);
        uint256 diffAfter = c.currentDifficulty();
        assertTrue(diffBefore == diffAfter);
    }
}
